const N = 70;
const particles = [];
for(let i=0;i<N;i++){
  particles.push({
    angle0: Math.random()*Math.PI*2,
    speed: (Math.random()*0.3+0.15) * (Math.random()<0.5?1:-1),
    rx: 0.24 + Math.random()*0.24,
    ry: 0.20 + Math.random()*0.26,
    size: 1.5 + Math.random()*2.5,
    color: PALETTE[Math.floor(Math.random()*PALETTE.length)],
    trail: []
  });
}

function hexToRgba(hex, a){
  const h = hex.replace('#','');
  const r = parseInt(h.substring(0,2),16);
  const g = parseInt(h.substring(2,4),16);
  const b = parseInt(h.substring(4,6),16);
  return `rgba(${r},${g},${b},${a})`;
}

function drawWingPair(s, colorA, colorB, mirror){
  ctx.save();
  ctx.scale(mirror,1);
  const grad = ctx.createLinearGradient(0,-s,s,s*0.3);
  grad.addColorStop(0, hexToRgba(colorA,0.85));
  grad.addColorStop(1, hexToRgba(colorB,0.35));
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.moveTo(0,0);
  ctx.bezierCurveTo(s*0.15,-s*0.35, s*0.95,-s*0.55, s*0.8,-s*0.05);
  ctx.bezierCurveTo(s*0.95,s*0.2, s*0.35,s*0.3, 0,0.02);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(0,0.02);
  ctx.bezierCurveTo(s*0.1,s*0.15, s*0.55,s*0.4, s*0.35,s*0.6);
  ctx.bezierCurveTo(s*0.15,s*0.55, s*0.05,s*0.25, 0,0.02);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function drawButterfly(x,y,flap,size){
  ctx.save();
  ctx.translate(x,y);
  const sx = 0.35 + 0.65*flap;
  ctx.save();
  ctx.scale(sx,1);
  drawWingPair(size, PALETTE[0], PALETTE[1], 1);
  ctx.restore();
  ctx.save();
  ctx.scale(sx,1);
  drawWingPair(size, PALETTE[0], PALETTE[1], -1);
  ctx.restore();
  ctx.fillStyle = hexToRgba(PALETTE[2],0.9);
  ctx.beginPath();
  ctx.ellipse(0,size*0.05, size*0.05, size*0.28, 0,0,Math.PI*2);
  ctx.fill();
  ctx.restore();
}

let start = null;
function frame(time){
  if(!start) start=time;
  const t = (time-start)*0.001;
  const w = W(), h = H();
  ctx.clearRect(0,0,w,h);
  const cx = w/2, cy = h/2;
  const minDim = Math.min(w,h);

  particles.forEach(p=>{
    const a = p.angle0 + t*p.speed;
    const rx = p.rx*minDim, ry = p.ry*minDim;
    const x = cx + Math.cos(a)*rx;
    const y = cy + Math.sin(a)*ry;
    p.trail.push({x,y});
    if(p.trail.length>6) p.trail.shift();
    for(let i=0;i<p.trail.length;i++){
      const pt = p.trail[i];
      const alpha = (i+1)/p.trail.length*0.4;
      ctx.beginPath();
      ctx.fillStyle = hexToRgba(p.color, alpha);
      ctx.shadowColor = hexToRgba(p.color,0.6);
      ctx.shadowBlur = 6;
      ctx.arc(pt.x, pt.y, p.size*((i+1)/p.trail.length), 0, Math.PI*2);
      ctx.fill();
    }
    ctx.shadowBlur = 0;
  });

  const ba = t*0.28;
  const brx = minDim*0.4, bry = minDim*0.33;
  const bx = cx + Math.cos(ba)*brx;
  const by = cy + Math.sin(ba)*bry + Math.sin(ba*2)*minDim*0.02;
  const flap = Math.sin(t*7)*0.5+0.5;
  const bsize = minDim*0.09;
  drawButterfly(bx,by,flap,bsize);

  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
